<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$viewer=current_user($pdo);$id=(string)($_GET['id']??'');$q=$pdo->prepare('SELECT c.*,u.username,u.display_name FROM collections c JOIN users u ON u.id=c.owner_user_id WHERE c.public_id=?');$q->execute([$id]);$c=$q->fetch();if(!$c||($c['visibility']!=='public'&&(!$viewer||$viewer['id']!=$c['owner_user_id']))){http_response_code(404);exit('Collection not found.');}$q=$pdo->prepare("SELECT a.public_id,a.text_commentary,a.published_at,s.public_id source_public_id,s.title,u.username,u.display_name FROM collection_items ci JOIN annotations a ON a.id=ci.annotation_id JOIN sources s ON s.id=a.source_id JOIN users u ON u.id=a.user_id WHERE ci.collection_id=? AND (a.visibility='public' OR a.user_id=?) AND a.status='published' ORDER BY ci.created_at DESC");$q->execute([$c['id'],(int)($viewer['id']??0)]);$items=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($c['title'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/explore.php">Explore</a><a href="/search.php">Search</a><?php if($viewer):?><a href="/saved.php">Saved</a><?php endif?></nav></header><main class="panel article"><div class="meta">Collection by <a href="/profile.php?u=<?=h($c['username'])?>"><?=h($c['display_name'])?></a> · <?=h($c['visibility'])?></div><h1><?=h($c['title'])?></h1><?php if($c['description']):?><p class="commentary"><?=nl2br(h($c['description']))?></p><?php endif?><?php if(!$items):?><div class="card">No annotations in this collection.</div><?php endif?><?php foreach($items as $a):?><article class="card"><div class="meta"><a href="/profile.php?u=<?=h($a['username'])?>"><?=h($a['display_name'])?></a> · <a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['title']?:'Source')?></a></div><?php if($a['text_commentary']):?><p><?=nl2br(h($a['text_commentary']))?></p><?php endif?><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a></article><?php endforeach?></main></body></html>
